CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','councillor','production','display','bridge','graphics')), password TEXT NOT NULL);
CREATE TABLE auth_sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE sessions(id TEXT PRIMARY KEY, title TEXT NOT NULL, number TEXT NOT NULL, date TEXT NOT NULL, place TEXT NOT NULL, statutory INTEGER NOT NULL CHECK(statutory>0), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','live','break','ended')), active_agenda TEXT, attendance_open INTEGER NOT NULL DEFAULT 0);
CREATE TABLE agenda(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), position INTEGER NOT NULL, title TEXT NOT NULL, UNIQUE(session_id,position));
CREATE TABLE attendance(session_id TEXT NOT NULL REFERENCES sessions(id), user_id TEXT NOT NULL REFERENCES users(id), present INTEGER NOT NULL, at TEXT NOT NULL, PRIMARY KEY(session_id,user_id));
CREATE TABLE votes(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), agenda_id TEXT NOT NULL REFERENCES agenda(id), question TEXT NOT NULL, rule TEXT NOT NULL CHECK(rule IN ('simple','absolute','qualified')), numerator INTEGER NOT NULL DEFAULT 2, denominator INTEGER NOT NULL DEFAULT 3, status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','OPEN','CLOSED','APPROVED','PUBLISHED')), opened_at TEXT, closed_at TEXT);
CREATE UNIQUE INDEX one_open_vote ON votes(session_id) WHERE status='OPEN';
CREATE TABLE electorate(vote_id TEXT NOT NULL REFERENCES votes(id), user_id TEXT NOT NULL REFERENCES users(id), present INTEGER NOT NULL, PRIMARY KEY(vote_id,user_id));
CREATE TABLE ballots(vote_id TEXT NOT NULL REFERENCES votes(id), user_id TEXT NOT NULL REFERENCES users(id), choice TEXT NOT NULL CHECK(choice IN ('YES','NO','ABSTAIN')), request_id TEXT NOT NULL, at TEXT NOT NULL, PRIMARY KEY(vote_id,user_id), UNIQUE(user_id,request_id));
CREATE TRIGGER ballot_only_open BEFORE INSERT ON ballots WHEN (SELECT status FROM votes WHERE id=NEW.vote_id)!='OPEN' BEGIN SELECT RAISE(ABORT,'vote_closed'); END;
CREATE TRIGGER immutable_ballot_update BEFORE UPDATE ON ballots BEGIN SELECT RAISE(ABORT,'immutable_ballot'); END;
CREATE TRIGGER immutable_ballot_delete BEFORE DELETE ON ballots BEGIN SELECT RAISE(ABORT,'immutable_ballot'); END;
CREATE TABLE results(vote_id TEXT PRIMARY KEY REFERENCES votes(id), version INTEGER NOT NULL, snapshot TEXT NOT NULL, approved_by TEXT NOT NULL REFERENCES users(id), approved_at TEXT NOT NULL);
CREATE TRIGGER immutable_result_update BEFORE UPDATE ON results BEGIN SELECT RAISE(ABORT,'immutable_result'); END;
CREATE TRIGGER immutable_result_delete BEFORE DELETE ON results BEGIN SELECT RAISE(ABORT,'immutable_result'); END;
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, vote_id TEXT, payload TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE audit(seq INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, payload TEXT NOT NULL, at TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TRIGGER immutable_audit_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE TRIGGER immutable_audit_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'immutable_audit'); END;
CREATE TABLE graphics_ready(vote_id TEXT PRIMARY KEY, version INTEGER NOT NULL, at INTEGER NOT NULL);
CREATE TABLE production(id INTEGER PRIMARY KEY CHECK(id=1), mode TEXT NOT NULL DEFAULT 'AUTO', hide_epoch INTEGER NOT NULL DEFAULT 0, bridge_at INTEGER, bridge_status TEXT, program_vote TEXT);
